--    missing, so nothing counted even for a real pair). Solo kill count = half of the VNG pair count.
--  * Dong Di (task 597): drops of the quest materials that have no source on this server.

-- the master part of the trial rewards is skipped when solo; keep the call harmless if unregistered
if AddMasterPRValue == nil then
	function AddMasterPRValue(n) end
end

function PTSD_IsPair()
	if GetTeamSize() ~= 2 then return 0 end
	local n = 0
	if IsCaptain() == 0 then n = GetTeamMember(1) else n = GetTeamMember(2) end
	if n and n > 0 and IsMasterPRRelation(n) == 1 then return 1 end
	return 0
end

-- 1 = may take / continue the master-apprentice quest (VNG pair, or solo outside any team)
function PTSD_JudgeRelation()
	if PTSD_IsPair() == 1 then return 1 end
	if GetTeamSize() <= 1 then return 1 end
	return 0
end

