-- solo kill count: half of the VNG pair formula 100+(floor(levels/10)-5)*40 with levels = 2 x own level
function PTSD_PR_SoloCount(lv)
	local c = floor((100 + (floor(2 * lv / 10) - 5) * 40) / 2)
	if c < 30 then c = 30 end
	return c
end

