function PTSD_PR_Credit(tpl)
	if GetTask(897) ~= tpl + 1 then return end
	local count = GetTask(898)
	if count <= 0 then return end
	if PTSD_JudgeRelation() ~= 1 then return end
	local nm = PTSD_PR_NAMES[tpl + 1] or ""
	if HaveIBBuff(215) == 0 then
		Msg2Player("Tr\245 Y\170u: V\223ng s\184ng \174\183 bi\213n m\202t, nhi\214m v\244 truy s\184t th\202t b\185i. H\183y h\241y r\229i nh\203n l\185i \235 V\226 s\173.")
		return
	end
	if count > 1 then
		SetTask(898, count - 1)
		Msg2Player("Tr\245 Y\170u: B\185n c\223n ph\182i gi\213t " .. (count - 1) .. " " .. nm .. "!")
	else
		SetTask(898, 0)
		TaskNote(42, 8)
		Msg2Player("Tr\245 Y\170u: B\185n \174\183 h\181ng ph\244c \174\241 " .. nm .. ", h\183y v\210 g\198p V\226 s\173 nh\203n th\173\235ng.")
	end
end

-- OnDeath body of the Tru Yeu target death scripts: killer + team members on the same map
function PTSD_PR_OnDeath(npcindex)
	local killer = PlayerIndex
	if not killer or killer <= 0 then return end
	local tpl = GetNpcTemplateID(npcindex)
	if not tpl then return end
	local w = GetWorldPos()
	local n = GetTeamSize()
	if n and n > 0 then
		local mem = {}
		local i = 1
		while i <= n do
			mem[i] = GetTeamMember(i)
			i = i + 1
		end
		i = 1
		while i <= n do
			if mem[i] and mem[i] > 0 then
				PlayerIndex = mem[i]
				if GetWorldPos() == w then PTSD_PR_Credit(tpl) end
			end
			i = i + 1
		end
		PlayerIndex = killer
	else
		PTSD_PR_Credit(tpl)
	end
end

