	if st == 7 and (w == 1044 or w == 1045 or w == 1047) then
		if GetItemLevel2(0, 4, 21) < 1 and PTSD_Roll(PTSD_RATE_KEY) then
			AddNormalItem(0, 4, 21, 1, 0, 0)
			Msg2Player("\167\171ng Nguy: nh\203n \174\173\238c Ng\228c H\173 Ph\239 (\174em \174\213n B\184 Gi\184m).")
		elseif HaveNormalItem(3, 79, 0, 0) < 1 and PTSD_Roll(PTSD_RATE_KEY) then
